82	    /// Creates a new `NativeJob` from a closure and an execution realm.
83	    pub fn with_realm<F>(f: F, realm: Realm) -> Self
84	    where
85	        F: FnOnce(&mut Context) -> JsResult<JsValue> + 'static,
86	    {
87	        Self {
88	            f: Box::new(f),
89	            realm: Some(realm),
90	        }
91	    }
92	
93	    /// Gets a reference to the execution realm of the job.
94	    #[must_use]
95	    pub const fn realm(&self) -> Option<&Realm> {
96	        self.realm.as_ref()
97	    }
98	
99	    /// Calls the native job with the specified [`Context`].
100	    ///
101	    /// # Note
102	    ///
103	    /// If the native job has an execution realm defined, this sets the running execution
104	    /// context to the realm's before calling the inner closure, and resets it after execution.
105	    pub fn call(self, context: &mut Context) -> JsResult<JsValue> {
106	        // If realm is not null, each time job is invoked the implementation must perform
107	        // implementation-defined steps such that execution is prepared to evaluate ECMAScript
108	        // code at the time of job's invocation.
109	        if let Some(realm) = self.realm {
110	            let old_realm = context.enter_realm(realm);
111	
112	            // Let scriptOrModule be GetActiveScriptOrModule() at the time HostEnqueuePromiseJob is
113	            // invoked. If realm is not null, each time job is invoked the implementation must
114	            // perform implementation-defined steps such that scriptOrModule is the active script or
115	            // module at the time of job's invocation.
116	            let result = (self.f)(context);
117	
118	            context.enter_realm(old_realm);
119	
120	            result
121	        } else {
122	            (self.f)(context)
123	        }
124	    }
125	}
